function generatePocket(){const s=readProfileFields();if(![s.depth,s.stepdown,s.safeZ,s.feed,s.plunge,s.rpm,s.pocketToolDiameter,s.pocketStepover].every(Number.isFinite)||s.depth<=0||s.stepdown<=0||s.safeZ<=0||s.feed<=0||s.plunge<=0||s.rpm<=0||s.pocketToolDiameter<=0||s.pocketStepover<=0||s.pocketStepover>s.pocketToolDiameter)throw Error('Enter positive pocket parameters; stepover must not exceed the tool diameter.');const chosen=objects.filter(o=>selectedIds.has(o.id)&&!hiddenLayers.has(o.layer));if(!chosen.some(isClosedVector))throw Error('Select one or more visible closed shapes to pocket, including their counter boundaries.');const contours=vgrooveContours(chosen),scale=1000,paths=contours.map(ring=>ring.slice(0,-1).map(p=>({X:Math.round(p.x*scale),Y:Math.round(p.y*scale)}))).filter(p=>p.length>=3);if(!paths.length)throw Error('No valid closed boundaries were found for pocketing.');const clipper=new ClipperLib.Clipper();clipper.AddPaths(paths,ClipperLib.PolyType.ptSubject,true);const normalized=new ClipperLib.Paths();if(!clipper.Execute(ClipperLib.ClipType.ctUnion,normalized,ClipperLib.PolyFillType.pftEvenOdd,ClipperLib.PolyFillType.pftEvenOdd)||!normalized.length)throw Error('Could not resolve the selected boundaries. Check for open or overlapping outlines.');const offsetter=new ClipperLib.ClipperOffset(2,.25);offsetter.AddPaths(normalized,ClipperLib.JoinType.jtRound,ClipperLib.EndType.etClosedPolygon);const loopLevels=[],maxOffsets=500,toolRadius=s.pocketToolDiameter/2;for(let i=0;i<maxOffsets;i++){const result=new ClipperLib.Paths(),inset=toolRadius+i*s.pocketStepover;offsetter.Execute(result,-inset*scale);if(!result.length)break;const loops=result.map(path=>{const points=path.map(p=>({x:p.X/scale,y:p.Y/scale}));if(points.length>2&&distance(points[0],points.at(-1))>1e-4)points.push({...points[0]});return{id:`pocket-${i}`,closed:true,points}}).filter(c=>c.points.length>=4);if(!loops.length)break;loopLevels.push(loops)}if(!loopLevels.length)throw Error('The tool does not fit inside the selected pocket area. Use a smaller tool or wider shape.');if(loopLevels.reduce((n,level)=>n+level.length,0)>5000)throw Error('Pocketing produced more than 5,000 clearing loops. Increase the tool diameter or stepover.');if(s.stepdown>s.depth)s.stepdown=s.depth;const passes=[];for(let d=Math.min(s.stepdown,s.depth);;d=Math.min(s.depth,d+s.stepdown)){passes.push(d);if(d>=s.depth-1e-9)break}profileSettings=s;const lines=['(Carve Studio pocket clearing)','(Nested inward offsets; no cutter compensation. Verify boundaries, stock zero and clearances.)',`(Tool diameter ${s.pocketToolDiameter.toFixed(3)} mm; stepover ${s.pocketStepover.toFixed(3)} mm.)`,`(Loops per depth: ${loopLevels.reduce((n,l)=>n+l.length,0)}; depth passes: ${passes.length}.)`,'G21 G90 G17 G94',`G0 Z${s.safeZ.toFixed(3)}`,`M3 S${Math.round(s.rpm)}`];let current={x:0,y:0};for(const depth of passes){for(let level=0;level<loopLevels.length;level++){const ordered=optimizeContourOrder(loopLevels[level],current);for(const contour of ordered){const start=contour.points[0];lines.push(`(Pocket pass depth ${depth.toFixed(3)} mm, inset ${(toolRadius+level*s.pocketStepover).toFixed(3)} mm)`,`G0 Z${s.safeZ.toFixed(3)}`,`G0 X${start.x.toFixed(3)} Y${start.y.toFixed(3)}`,`G1 Z-${depth.toFixed(3)} F${s.plunge.toFixed(1)}`);for(const p of contour.points.slice(1))lines.push(`G1 X${p.x.toFixed(3)} Y${p.y.toFixed(3)} F${s.feed.toFixed(1)}`);lines.push(`G0 Z${s.safeZ.toFixed(3)}`);current={...start}}}}lines.push('M5','M30');generatedGcode=lines.join('\n')+'\n';const preview=loopLevels.flat();profileContours=preview;generatedOperation='pocket';const layer=$('#toolpath-preview');layer.replaceChildren();for(const contour of preview){const el=document.createElementNS(svgNS,'polyline');el.setAttribute('points',contour.points.map(p=>`${p.x},${stock.height-p.y}`).join(' '));el.setAttribute('class','cam-pocket-path');layer.append(el)}$('#gcode-preview').value=generatedGcode;$('#gcode-preview').hidden=false;$('#save-gcode').disabled=false;$('#load-visualizer').disabled=false;profileStatus(`Pocket preview ready · ${preview.length} offset loops per depth · ${passes.length} depth passes · ${s.pocketStepover.toFixed(2)} mm stepover. Simulate before cutting.`)}
