canvas.addEventListener('pointermove',e=>{const p=point(e);$('#coordinates').innerHTML=`X ${p.x.toFixed(1)}&nbsp;&nbsp; Y ${p.y.toFixed(1)} mm`;if(['select','trim'].includes(activeTool)&&!drag&&!drawStart){const near=nearestObjectAt(p);canvas.style.cursor=near?'pointer':''}if(drag?.mode==='text-place'){const anchor=snapPoint(p);if(anchor.x!==drag.anchor.x||anchor.y!==drag.anchor.y){drag.anchor=anchor;updateTextPreview(anchor)}}if(drag?.mode==='move'){const moved=Math.hypot(e.clientX-drag.startClientX,e.clientY-drag.startClientY)>3;if(moved){const target=snapPoint(p),totalX=target.x-drag.origin.x,totalY=target.y-drag.origin.y,dx=totalX-drag.applied.x,dy=totalY-drag.applied.y;if(dx||dy){if(!drag.undoRecorded){remember();drag.undoRecorded=true}for(const o of drag.items)shift(o,dx,dy);drag.applied={x:totalX,y:totalY};redraw()}}}if(drag?.mode==='pan'){view.tx+=e.clientX-drag.last.x;view.ty+=e.clientY-drag.last.y;drag.last={x:e.clientX,y:e.clientY};renderView()}if(drag?.mode==='pending-area'&&Math.hypot(e.clientX-drag.startClientX,e.clientY-drag.startClientY)>4){drag.mode='marquee';drag.moved=true;drawSelectionBox(drag.start,p,e.clientX<drag.startClientX)}if(drag?.mode==='marquee'){if(Math.hypot(e.clientX-drag.startClientX,e.clientY-drag.startClientY)>4)drag.moved=true;if(drag.moved)drawSelectionBox(drag.start,p,e.clientX<drag.startClientX)}if(drawStart){if(drawGesture&&Math.hypot(e.clientX-drawGesture.startClientX,e.clientY-drawGesture.startClientY)>4)drawGesture.moved=true;updateDrawingPreview(snapPoint(p))}});
canvas.addEventListener('pointerdown',e=>{const p=point(e);canvas.setPointerCapture(e.pointerId);if(activeTool==='pan'||e.button===1){drag={mode:'pan',last:{x:e.clientX,y:e.clientY}};canvas.dataset.panning='true';return}if(activeTool==='trim'){const o=nearestObjectAt(p);if(o)trimVectorAt(o.id,p);return}if(activeTool==='text'){if(!$('#text-content').value.trim()){$('#text-content').focus();profileStatus('Enter text before placing it.',true);return}const anchor=snapPoint(p);drag={mode:'text-place',anchor};updateTextPreview(anchor);return}if(activeTool==='select'){if(e.target.closest('#selection-center')){const items=objects.filter(item=>selectedIds.has(item.id)&&!hiddenLayers.has(item.layer));if(items.length)drag={mode:'move',items,origin:p,applied:{x:0,y:0},startClientX:e.clientX,startClientY:e.clientY,undoRecorded:false};return}const hit=nearestObjectAt(p);if(hit){const o=selectAt(e,p);if(o?.areaEdit)return;if(o&&selectedIds.has(o.id))drag={mode:'move',items:objects.filter(item=>selectedIds.has(item.id)),origin:p,applied:{x:0,y:0},startClientX:e.clientX,startClientY:e.clientY,undoRecorded:false};else drag={mode:'pending-area',start:p,startClientX:e.clientX,startClientY:e.clientY,baseIds:e.shiftKey?new Set(selectedIds):new Set(),additive:e.shiftKey,moved:false}}else drag={mode:'pending-area',start:p,startClientX:e.clientX,startClientY:e.clientY,baseIds:e.shiftKey?new Set(selectedIds):new Set(),additive:e.shiftKey,moved:false};return}if(!drawStart){drawStart=snapPoint(p);drawGesture={phase:'first',startClientX:e.clientX,startClientY:e.clientY,moved:false}}else drawGesture={phase:'second',startClientX:e.clientX,startClientY:e.clientY,moved:false};updateDrawingPreview(snapPoint(p))});
canvas.addEventListener('dblclick',e=>{if(activeTool!=='select'||e.target.closest('#selection-center'))return;const item=nearestObjectAt(point(e));if(!item)return;selectedRegion=null;selectedIds=connectedSelectionIds(item.id);if((generatedOperation==='profile'&&profileSettings.scope==='selected'||generatedOperation==='drill'&&profileSettings.drillScope==='selected'||generatedOperation==='vgroove'||generatedOperation==='pocket')&&generatedGcode)clearProfilePreview('Selection changed. Generate the toolpath preview again.');redraw();e.preventDefault()});
canvas.addEventListener('pointerup',e=>{if(drag?.mode==='pan'){drag=null;canvas.dataset.panning='false';return}if(drag?.mode==='text-place'){const anchor=snapPoint(point(e));drag=null;textPreviewToken++;$('#drawing-preview').replaceChildren();commitBlockTextAt(anchor);return}if(drag?.mode==='pending-area'){const pending=drag;drag=null;const p=point(e);if(Math.hypot(e.clientX-pending.startClientX,e.clientY-pending.startClientY)<=4)selectAt(e,p);else{drag=pending;drag.mode='marquee';finishMarquee(e)}return}if(drag?.mode==='marquee'){finishMarquee(e);return}if(!drawStart){drag=null;return}const p=snapPoint(point(e)),moved=drawGesture?.moved||Math.hypot(e.clientX-(drawGesture?.startClientX??e.clientX),e.clientY-(drawGesture?.startClientY??e.clientY))>4;if(drawGesture?.phase==='first'&&!moved){drawGesture=null;updateDrawingPreview(p);return}finishDrawing(p)});
