$('#new-project').onclick=async()=>{if(objects.length||toolpathJobs.length){const choice=await askSaveBeforeNew();if(choice==='cancel')return;if(choice==='save'&&!await saveProjectFile())return}objects=[];customLayers=['Default'];activeLayer='Default';hiddenLayers.clear();selectedIds.clear();selectedRegion=null;nextId=1;toolpathJobs=[];nextToolpathId=1;renderToolpathList();stock.width=300;stock.height=200;stock.thickness=18;stockManuallySet=false;gridSettings.enabled=false;gridSettings.resolution=5;$('#stock-width').value=300;$('#stock-height').value=200;$('#stock-thickness').value=18;$('#auto-stock-size').checked=true;undoStack=[];redoStack=[];clearProfilePreview();setProjectName('Untitled project');resizeBoard();fitView();redraw()};
