window.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(e.key==='Escape'&&drawStart){drawStart=null;drawGesture=null;$('#drawing-preview').replaceChildren();return}if(e.key==='Delete'||e.key==='Backspace'){if(selectedIds.size){e.preventDefault();$('#delete-selected').click()}return}if(!(e.ctrlKey||e.metaKey))return;const key=e.key.toLowerCase();if(key==='z'){e.preventDefault();(e.shiftKey?$('#redo'):$('#undo')).click()}else if(key==='y'){e.preventDefault();$('#redo').click()}else if(key==='s'){e.preventDefault();$('#save-project').click()}else if(key==='a'){e.preventDefault();selectedIds=new Set(objects.filter(o=>!hiddenLayers.has(o.layer)).map(o=>o.id));redraw()}else if(key==='d'){e.preventDefault();$('#duplicate-selected').click()}});
